// checked = every task list selected, indeterminate = some but not all, unchecked = none.
const totalTaskLists = Array.isArray(activeSites)
    ? activeSites.reduce((total: number, site: any) => total + (site.TaskLists?.length || 0), 0)
    : 0;
const selectedTaskListCount = activeSitesSelectedItems?.length || 0;
const allSelectedSites = totalTaskLists > 0 && selectedTaskListCount === totalTaskLists;
const someSelectedSites = selectedTaskListCount > 0 && selectedTaskListCount < totalTaskLists;
const selectAllSitesRef = React.useRef<HTMLInputElement>(null);
useEffect(() => {
    if (selectAllSitesRef.current) {
        selectAllSitesRef.current.indeterminate = someSelectedSites;
    }
}, [someSelectedSites]);

